ForeverCoaching=ForeverCoaching or {}
-- Qualitative toolkit guidance. Availability is checked against the selected
-- allocation or the current client's spellbook; this is not a DPS tier list.
local FC=ForeverCoaching
FC.SpecScenarioProfiles={}
local function profile(class,index,name,role,identity,single,group,burst,movement,resource,utility)
 FC.SpecScenarioProfiles[class]=FC.SpecScenarioProfiles[class] or {}
 FC.SpecScenarioProfiles[class][index]={name=name,role=role,identity=identity,single=single,group=group,burst=burst,movement=movement,resource=resource,utility=utility}
end
